async (page) => {
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.goto('file:///C:/Users/Wendy/Desktop/Projects/wdc/prototypes/client-workspace/artifact.html');
  await page.setViewportSize({width:1440,height:1000});
  await page.getByRole('button',{name:'Client portal',exact:true}).click();
  await page.getByRole('button',{name:'Review the posts',exact:true}).click();
  await page.getByRole('button',{name:'Approve version 2',exact:true}).click();
  if(!await page.getByRole('heading',{name:'Version 2 approved',exact:true}).count())throw new Error('Approval not shown');
  await page.getByRole('button',{name:'Close dialog',exact:true}).click();
  await page.getByRole('button',{name:'Studio',exact:true}).click();
  const metrics=await page.locator('.metric').allTextContents();if(metrics[0]!=='0')throw new Error('Overview did not update after approval');
  await page.getByRole('button',{name:'Review the posts',exact:true}).click();
  await page.getByRole('button',{name:'Try a newer version',exact:true}).click();
  await page.getByRole('button',{name:'Close dialog',exact:true}).click();
  if(await page.getByRole('button',{name:'Approve version 3',exact:true}).count())throw new Error('Studio can approve as client');
  await page.getByRole('button',{name:'Client portal',exact:true}).click();
  await page.getByRole('button',{name:'Review the posts',exact:true}).click();
  if(!await page.getByRole('button',{name:'Approve version 3',exact:true}).count())throw new Error('New version not reviewable');
  if(!await page.getByText('Earlier sample decision retained',{exact:true}).count())throw new Error('Approval history lost');
  await page.getByRole('button',{name:'Client portal',exact:true}).click();
  await page.getByRole('button',{name:'Open work',exact:true}).first().click();
  await page.getByRole('button',{name:'Work',exact:true}).click();
  if(await page.getByText('Internal review',{exact:true}).count())throw new Error('Internal draft exposed');
  if(await page.getByRole('button',{name:'Change planned time',exact:true}).count())throw new Error('Studio controls exposed');
  await page.waitForTimeout(600);await page.screenshot({path:'output/playwright/client-workspace-client.png'});
  await page.getByRole('button',{name:'Open post',exact:true}).click();
  if(!await page.getByText(/Caption:/).count())throw new Error('Social detail missing caption');
  await page.getByRole('button',{name:'Close dialog',exact:true}).click();
  await page.getByRole('button',{name:'Software & AI',exact:true}).click();
  await page.locator('[aria-label="Project sections"]').getByRole('button',{name:'Overview',exact:true}).click();
  await page.getByRole('button',{name:'Open current work',exact:true}).click();
  if(await page.getByText(/Caption:/).count())throw new Error('Social caption leaked to software detail');
  await page.getByRole('button',{name:'Close dialog',exact:true}).click();
  await page.setViewportSize({width:320,height:900});
  await page.getByRole('button',{name:'Open the menu',exact:true}).click();
  if(!await page.getByRole('heading',{name:'Navigation',exact:true}).count())throw new Error('Mobile drawer missing');
  await page.keyboard.press('Escape');
  if(await page.locator('#preview-dialog').evaluate(d=>d.open))throw new Error('Escape did not close');
  if(errors.length)throw new Error(JSON.stringify(errors));
  return {portableArtifact:'passed',exactVersion:'approved v2; v3 requires new decision; history retained',overviewCounts:'reflect sample decisions',roleVisibility:'internal drafts and studio-only controls excluded',serviceDetail:'distinct social and software detail verified',mobileNavigation:'dialog opens and Escape closes',pageErrors:errors};
}
